import{_ as a}from"./chunks/image.IC3XLs8_.js";import{u as s}from"./chunks/useReporter.D4n0v9NN.js";import{c as n,o as e,b2 as t}from"./chunks/framework.BRCYMVIo.js";const p="/assets/original.r26ZHGze.jpeg",l="/assets/version1.CIwTuHBm.png",i="/assets/ref.D0Ec4CJw.jpeg",o="/assets/version2.1naWKUL8.png",d=t('<blockquote><p>给 Codex 一张 UI 截图，它能看出问题，也能给出一套像样的改版方案吗？这次我拿一个移动端直播评论界面做实验，看看它究竟是设计搭档，还是只会说“建议增加留白”的气氛组。</p></blockquote><p><img src="'+a+'" alt="Codex 工作界面"></p><h2 id="先说结论" tabindex="-1">先说结论 <a class="header-anchor" href="#先说结论" aria-label="Permalink to &quot;先说结论&quot;">​</a></h2><p>Codex 可以很好地完成<strong>界面诊断、需求梳理和方案迭代</strong>，但它并不会在第一次就读懂所有产品语义。想得到真正可用的结果，关键不是一句“帮我优化得好看一点”，而是持续补充三类信息：</p><ul><li>业务里有哪些角色，角色之间是什么关系；</li><li>页面运行在什么设备和环境中；</li><li>哪些视觉规律必须保留，哪些问题可以大胆修改。</li></ul><p>这次设计一共迭代了两版。第一版“看起来更精致”，第二版才真正“像这个产品该有的样子”。中间的差别，正好说明了怎样更有效地让 Codex 参与 UI 设计。</p><h2 id="第一回合-只给截图-让-codex-找问题" tabindex="-1">第一回合：只给截图，让 Codex 找问题 <a class="header-anchor" href="#第一回合-只给截图-让-codex-找问题" aria-label="Permalink to &quot;第一回合：只给截图，让 Codex 找问题&quot;">​</a></h2><p>这是最初的界面：</p><p><img src="'+p+`" alt="原始直播评论界面"></p><p>我给出的第一条要求非常简单：</p><blockquote><p>这个 UI 看起来有些不协调。请分析具体问题，并给出可执行的优化建议。</p></blockquote><p>Codex 的判断很快抓住了重点：问题不在某个按钮的圆角够不够圆，而在于<strong>视频主体、评论流和底部操作栏同时争夺视觉注意力</strong>。尤其是那条超长评论，几乎凭一己之力承包了整个屏幕下半场。</p><h3 id="_1-长评论过度抢镜" tabindex="-1">1. 长评论过度抢镜 <a class="header-anchor" href="#_1-长评论过度抢镜" aria-label="Permalink to &quot;1. 长评论过度抢镜&quot;">​</a></h3><p>大段文字气泡接近屏幕宽度，不仅遮住人物，还成为页面里视觉权重最高的元素。用户本来是来看直播的，结果先被一堵“文字墙”迎面拦住。</p><p>可以这样处理：</p><ul><li>评论最大宽度控制在屏幕的 <code>68%–72%</code>；</li><li>普通评论默认最多显示 <code>2</code> 行，超出后提供“展开”；</li><li>同屏保留最近 <code>3–4</code> 条，旧消息向上淡出；</li><li>正文字号使用 <code>15–16px</code>，行高保持在 <code>22–24px</code>；</li><li>点击评论后再查看完整内容，不让单条消息无限撑高列表。</li></ul><h3 id="_2-气泡颜色跟着背景-变脸" tabindex="-1">2. 气泡颜色跟着背景“变脸” <a class="header-anchor" href="#_2-气泡颜色跟着背景-变脸" aria-label="Permalink to &quot;2. 气泡颜色跟着背景“变脸”&quot;">​</a></h3><p>同一个半透明气泡覆盖绿幕、皮肤和衣服后，分别呈现绿色、褐色和黑色，看起来像用了好几套配色。透明并不等于轻盈；如果缺少稳定的底色和对比度，它只会把复杂的视频背景一起带进组件里。</p><p>第一轮建议使用一套更稳定的样式：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>背景：rgba(18, 20, 24, 0.72)</span></span>
<span class="line"><span>边框：rgba(255, 255, 255, 0.10)</span></span>
<span class="line"><span>文字：#FFFFFF</span></span>
<span class="line"><span>圆角：10–12px</span></span></code></pre></div><p>必要时可以增加轻微的背景模糊或阴影，让文字经过明暗变化剧烈的画面时仍然清晰。</p><h3 id="_3-评论列表挡住了真正的主角" tabindex="-1">3. 评论列表挡住了真正的主角 <a class="header-anchor" href="#_3-评论列表挡住了真正的主角" aria-label="Permalink to &quot;3. 评论列表挡住了真正的主角&quot;">​</a></h3><p>评论从人物肩部开始堆叠，长消息直接覆盖主体。更合理的做法是给评论区划定固定范围，让它待在左下角，并与输入栏保持 <code>12–16px</code> 间距。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────── 视频主体 ────────────┐</span></span>
<span class="line"><span>│                                  │</span></span>
<span class="line"><span>│              人物                │</span></span>
<span class="line"><span>│                                  │</span></span>
<span class="line"><span>│  用户A  快递怎么发               │</span></span>
<span class="line"><span>│  用户B  优惠券有吗               │</span></span>
<span class="line"><span>│  用户C  大段文字内容…  展开       │</span></span>
<span class="line"><span>│                                  │</span></span>
<span class="line"><span>│  [发送评论………………] [发送]        │</span></span>
<span class="line"><span>└──────────────────────────────────┘</span></span></code></pre></div><h3 id="_4-底部操作状态互相矛盾" tabindex="-1">4. 底部操作状态互相矛盾 <a class="header-anchor" href="#_4-底部操作状态互相矛盾" aria-label="Permalink to &quot;4. 底部操作状态互相矛盾&quot;">​</a></h3><p>原界面的输入框像是禁用状态，旁边的“发送”按钮却亮得十分积极。一个说“现在不能发”，另一个说“快点按我”，用户自然会犹豫。</p><p>建议统一交互状态：</p><ul><li>输入为空时，发送按钮使用明确的禁用态；</li><li>输入文字后，发送按钮再切换为品牌主色；</li><li>输入框和按钮高度统一为 <code>44–48px</code>；</li><li>底部容器使用半透明深色浮层，减少大块实灰色带来的压迫感；</li><li>通过 <code>env(safe-area-inset-bottom)</code> 避开移动端系统手势区域。</li></ul><h3 id="_5-巨大的-×-不知道要关闭谁" tabindex="-1">5. 巨大的“×”不知道要关闭谁 <a class="header-anchor" href="#_5-巨大的-×-不知道要关闭谁" aria-label="Permalink to &quot;5. 巨大的“×”不知道要关闭谁&quot;">​</a></h3><p>底部的 <code>×</code> 与发送按钮并列，可能被理解为清空输入，也可能是退出评论，甚至像是在关闭整个直播。图标认识，语义却不认识，是典型的操作歧义。</p><p>应该根据真实功能选择位置和图标：</p><ul><li>关闭评论面板：放在面板右上角，使用至少 <code>44px</code> 的触控区域；</li><li>清空输入内容：放在输入框内部右侧，并且只在有内容时出现；</li><li>收起键盘：使用键盘收起图标，不使用 <code>×</code>。</li></ul><h3 id="_6-评论缺少角色身份" tabindex="-1">6. 评论缺少角色身份 <a class="header-anchor" href="#_6-评论缺少角色身份" aria-label="Permalink to &quot;6. 评论缺少角色身份&quot;">​</a></h3><p>所有气泡都只有正文，更像一组快捷问题，而不像正在发生的对话。如果这些内容是真实评论，至少需要展示用户名或角色；如果它们是预设问题，就应该改成输入框上方的横向短标签，而不是伪装成聊天记录。</p><p>这一步也暴露了第一条提示词的问题：<strong>我只给了画面，没有告诉 Codex 画面背后的业务规则。</strong></p><h2 id="第二回合-补充角色关系-生成第一版方案" tabindex="-1">第二回合：补充角色关系，生成第一版方案 <a class="header-anchor" href="#第二回合-补充角色关系-生成第一版方案" aria-label="Permalink to &quot;第二回合：补充角色关系，生成第一版方案&quot;">​</a></h2><p>接着，我补充了一条非常关键的信息：</p><blockquote><p>评论列表里只有“我”和“主播”两个角色。请按上面的建议优化，并生成一版设计图。</p></blockquote><p>有了角色关系后，第一版方案采用了典型的双人会话结构：</p><ul><li>主播消息左对齐，使用中性深色气泡；</li><li>“我”的消息右对齐，使用品牌紫色气泡；</li><li>评论层最多展示 <code>4</code> 条消息，长内容限制为两行；</li><li>关闭按钮移动到评论面板右上角；</li><li>底部只保留输入框和发送按钮。</li></ul><p><img src="`+l+'" alt="第一版设计：双角色会话面板"></p><p>单独看，这一版已经整洁了很多：身份明确、按钮状态统一、长文本也不再横冲直撞。但放回直播场景后，总觉得哪里不对。</p><p>问题就在于它<strong>太像聊天软件，反而不像直播评论</strong>。厚重的整块面板盖住了大量视频内容，左右对话虽然清晰，却让评论流失去了直播间应有的轻快和连续感。</p><p>第一版解决了“乱”，却付出了“重”的代价。</p><h2 id="第三回合-给参考图-也给产品约束" tabindex="-1">第三回合：给参考图，也给产品约束 <a class="header-anchor" href="#第三回合-给参考图-也给产品约束" aria-label="Permalink to &quot;第三回合：给参考图，也给产品约束&quot;">​</a></h2><p>这一次，我没有继续用“再好看一点”这种玄学指令，而是给了 Codex 一张参考图：</p><p><img src="'+i+'" alt="直播评论界面参考图"></p><p>同时把真正想要的设计规律说清楚：</p><blockquote><p>参考这张图的评论列表风格。评论不需要厚重的整体底色，所有角色都左对齐；列表超过一定高度后，顶部内容渐变隐藏；文字输入框占据左下方的大部分宽度，右侧放一个全屏按钮。应用运行在移动端浏览器中。</p></blockquote><p>这条提示词比第一条有效得多，因为它同时包含了：</p><table tabindex="0"><thead><tr><th>信息类型</th><th>明确内容</th></tr></thead><tbody><tr><td>视觉参考</td><td>直播评论流，而不是聊天面板</td></tr><tr><td>布局规则</td><td>全部左对齐，输入框左宽右窄</td></tr><tr><td>层级要求</td><td>不使用厚重的整体底色</td></tr><tr><td>动态行为</td><td>旧消息在顶部渐隐</td></tr><tr><td>运行环境</td><td>移动端浏览器</td></tr><tr><td>关键操作</td><td>输入评论与进入全屏</td></tr></tbody></table><p>最终得到第二版方案：</p><p><img src="'+o+`" alt="第二版设计：轻量直播评论层"></p><p>这一版明显更接近目标：</p><ul><li>所有消息统一左对齐，阅读路径稳定；</li><li>通过“我”和“主播”的文字颜色区分角色，不再依赖左右站位；</li><li>每条消息只保留轻量的半透明底色，视频仍然是页面主角；</li><li>顶部渐隐既表达了列表可以继续滚动，也让旧消息自然退场；</li><li>输入框占据底部主要空间，全屏按钮保持独立且容易触达；</li><li>底部预留安全区，更适合移动端浏览器和全面屏设备。</li></ul><p>这次并没有堆更多装饰，结果反而更完整。对直播界面来说，“存在感低”本身就是一种设计能力。</p><h2 id="两版方案为什么差这么多" tabindex="-1">两版方案为什么差这么多 <a class="header-anchor" href="#两版方案为什么差这么多" aria-label="Permalink to &quot;两版方案为什么差这么多&quot;">​</a></h2><p>第一版和第二版的差异，并不只是配色或圆角发生了变化，而是 Codex 对产品模型的理解发生了变化：</p><table tabindex="0"><thead><tr><th>对比项</th><th>第一版</th><th>第二版</th></tr></thead><tbody><tr><td>产品模型</td><td>双人聊天</td><td>直播评论流</td></tr><tr><td>角色区分</td><td>左右位置 + 气泡颜色</td><td>用户名颜色</td></tr><tr><td>评论容器</td><td>厚重的整体面板</td><td>轻量的单条气泡</td></tr><tr><td>视频占比</td><td>被面板明显遮挡</td><td>保持为视觉主体</td></tr><tr><td>消息消失方式</td><td>面板内滚动</td><td>顶部渐变淡出</td></tr><tr><td>底部操作</td><td>输入框 + 发送按钮</td><td>长输入框 + 全屏按钮</td></tr></tbody></table><p>这说明参考图最有价值的部分不是“照着画”，而是帮助 Codex 识别正确的<strong>界面类型和视觉语法</strong>。一旦产品模型判断错了，细节做得再漂亮，也只是在错误的方向上精装修。</p><h2 id="一套更好用的-ui-优化提示词" tabindex="-1">一套更好用的 UI 优化提示词 <a class="header-anchor" href="#一套更好用的-ui-优化提示词" aria-label="Permalink to &quot;一套更好用的 UI 优化提示词&quot;">​</a></h2><p>以后再让 Codex 分析或改造界面，可以直接按下面的结构组织信息：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这是一个【产品类型】页面，运行在【设备 / 平台】。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>核心用户是【用户类型】，主要任务是【关键任务】。</span></span>
<span class="line"><span>页面包含【角色或内容类型】，它们之间的关系是【业务关系】。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>当前问题：</span></span>
<span class="line"><span>1. 【问题一】</span></span>
<span class="line"><span>2. 【问题二】</span></span>
<span class="line"><span>3. 【问题三】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请参考附图中的【具体设计规律】，但不要照搬【不适用的部分】。</span></span>
<span class="line"><span>必须保留：【不可修改的元素】。</span></span>
<span class="line"><span>可以调整：【允许修改的范围】。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请先分析信息层级和交互问题，再给出布局、尺寸、状态和动效建议，</span></span>
<span class="line"><span>最后生成一版适配【目标尺寸】的高保真设计图。</span></span></code></pre></div><p>套用到这次案例，大致就是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这是一个运行在移动端浏览器中的直播页面，视频是视觉主体。</span></span>
<span class="line"><span>评论区只有“我”和“主播”两个角色，消息按时间顺序出现。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请优化评论列表和底部输入区：</span></span>
<span class="line"><span>- 所有评论左对齐，通过角色名颜色区分身份；</span></span>
<span class="line"><span>- 不使用覆盖视频的大面积底板；</span></span>
<span class="line"><span>- 长消息最多显示两行，旧消息在列表顶部渐隐；</span></span>
<span class="line"><span>- 输入框占底部大部分宽度，右侧提供全屏按钮；</span></span>
<span class="line"><span>- 触控区域不小于 44px，并适配底部安全区。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请先说明设计取舍，再生成 1216 × 2640 的高保真方案图。</span></span></code></pre></div><h2 id="使用-codex-做-ui-设计的几点体会" tabindex="-1">使用 Codex 做 UI 设计的几点体会 <a class="header-anchor" href="#使用-codex-做-ui-设计的几点体会" aria-label="Permalink to &quot;使用 Codex 做 UI 设计的几点体会&quot;">​</a></h2><h3 id="先说业务-再谈好不好看" tabindex="-1">先说业务，再谈好不好看 <a class="header-anchor" href="#先说业务-再谈好不好看" aria-label="Permalink to &quot;先说业务，再谈好不好看&quot;">​</a></h3><p>“不好看”通常只是结果，“谁在用、要做什么、什么最重要”才是原因。角色、设备、操作目标越明确，Codex 给出的建议越能落地。</p><h3 id="参考图要指出-参考哪里" tabindex="-1">参考图要指出“参考哪里” <a class="header-anchor" href="#参考图要指出-参考哪里" aria-label="Permalink to &quot;参考图要指出“参考哪里”&quot;">​</a></h3><p>只说“按这张图做”，很容易把配色、装饰和布局全部混在一起。明确告诉它要学习的是评论对齐方式、透明层级还是底部操作结构，结果会稳定很多。</p><h3 id="第一版适合暴露问题-不必急着定稿" tabindex="-1">第一版适合暴露问题，不必急着定稿 <a class="header-anchor" href="#第一版适合暴露问题-不必急着定稿" aria-label="Permalink to &quot;第一版适合暴露问题，不必急着定稿&quot;">​</a></h3><p>第一版不够好并不代表工具没用。恰恰相反，它能让原本模糊的偏好变得具体：看到厚重面板之后，我才更确定自己需要的是轻量评论流。</p><h3 id="设计图之后仍然需要验证" tabindex="-1">设计图之后仍然需要验证 <a class="header-anchor" href="#设计图之后仍然需要验证" aria-label="Permalink to &quot;设计图之后仍然需要验证&quot;">​</a></h3><p>静态设计稿不能替代真实页面。进入开发阶段后，还需要检查：</p><ul><li>极长评论和连续消息是否会挤压布局；</li><li>键盘弹出后输入区是否仍然可见；</li><li><code>100vh</code> 在移动端浏览器地址栏伸缩时是否稳定；</li><li>全屏 API 在 iOS Safari 和 Android 浏览器中的行为差异；</li><li>明亮、复杂的视频背景下，文字对比度是否足够；</li><li>安全区、横竖屏切换和最小触控尺寸是否符合预期。</li></ul><h2 id="最后" tabindex="-1">最后 <a class="header-anchor" href="#最后" aria-label="Permalink to &quot;最后&quot;">​</a></h2><p>Codex 暂时不能取代 UI 设计师，因为真正困难的部分从来不只是把界面画得整齐，而是理解业务、判断取舍，并知道什么时候该让元素退后一步。</p><p>但把它当成一个能看截图、能拆问题、还能快速出方案的设计搭档，它已经非常实用。它不会因为你推翻第一版而不耐烦，也不介意你半夜突然补一句“所有评论还是左对齐吧”。</p><p>这次实验最重要的结论是：<strong>AI 生成结果的上限，往往取决于我们描述问题的精度。</strong> 当需求从“帮我美化一下”变成清晰的产品规则，设计才真正开始。</p>`,79),r=[d],g=JSON.parse('{"title":"用 Codex 做 UI 设计：从截图诊断到两轮重构","description":"一次完整的 Codex UI 设计实战：从截图诊断直播评论界面，到结合业务约束与参考图完成两轮重构，并总结可复用的提示词方法。","frontmatter":{"title":"用 Codex 做 UI 设计：从截图诊断到两轮重构","head":[["meta",{"name":"description","content":"一次完整的 Codex UI 设计实战：从截图诊断直播评论界面，到结合业务约束与参考图完成两轮重构，并总结可复用的提示词方法。"}],["meta",{"name":"keywords","content":"Codex, UI 设计, AI 辅助设计, 界面优化, 移动端设计, 直播评论区, 提示词"}]],"layout":"doc","outline":"deep"},"headers":[],"relativePath":"skills/note.md","filePath":"skills/note.md","lastUpdated":1785759023000}'),c={name:"skills/note.md"},k=Object.assign(c,{setup(h){return s(),(u,b)=>(e(),n("div",null,r))}});export{g as __pageData,k as default};
